  playTurn(targetPlayer) {
    const player = this.currentPlayer();
    let playedCard = null;
    if (player.hasCard(new Missed())) {
      playedCard = player.hand.find(card => card instanceof Missed);
    } else if (player.hasCard(new Bang())) {
      playedCard = player.hand.find(card => card instanceof Bang);
    }
    if (playedCard !== null) {
      this.playCard(playedCard, targetPlayer);
    } else if (player.hasCard(new Beer())) {
      this.playCard(player.hand.find(card => card instanceof Beer), player);
    }
    this.nextPlayer();
  }
}

